#!/bin/bash
# Uninstall script for WiFiman Desktop
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling WiFiman Desktop..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping WiFiman Desktop if running..."
pkill -f "WiFiman Desktop" 2>/dev/null || true

# Unload service wifiman-desktop
echo "Unloading service wifiman-desktop..."
launchctl unload -w /Library/LaunchAgents/wifiman-desktop.plist 2>/dev/null || true
launchctl unload -w /Library/LaunchDaemons/wifiman-desktop.plist 2>/dev/null || true
launchctl unload -w ~/Library/LaunchAgents/wifiman-desktop.plist 2>/dev/null || true

# Remove $HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/ui.wifiman-desktop.sfl*
echo "Removing $HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/ui.wifiman-desktop.sfl*..."
if [ -d "$HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/ui.wifiman-desktop.sfl*" ]; then
    rm -rf "$HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/ui.wifiman-desktop.sfl*" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/ui.wifiman-desktop.sfl*" ]; then
    rm -f "$HOME/Library/Application Support/com.apple.sharedfilelist/com.apple.LSSharedFileList.ApplicationRecentDocuments/ui.wifiman-desktop.sfl*" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/wifiman-desktop
echo "Removing $HOME/Library/Application Support/wifiman-desktop..."
if [ -d "$HOME/Library/Application Support/wifiman-desktop" ]; then
    rm -rf "$HOME/Library/Application Support/wifiman-desktop" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/wifiman-desktop" ]; then
    rm -f "$HOME/Library/Application Support/wifiman-desktop" 2>/dev/null || true
fi

# Remove $HOME/Library/Logs/wifiman-desktop
echo "Removing $HOME/Library/Logs/wifiman-desktop..."
if [ -d "$HOME/Library/Logs/wifiman-desktop" ]; then
    rm -rf "$HOME/Library/Logs/wifiman-desktop" 2>/dev/null || true
elif [ -f "$HOME/Library/Logs/wifiman-desktop" ]; then
    rm -f "$HOME/Library/Logs/wifiman-desktop" 2>/dev/null || true
fi

# Remove $HOME/Library/Preferences/ui.wifiman-desktop.plist
echo "Removing $HOME/Library/Preferences/ui.wifiman-desktop.plist..."
if [ -d "$HOME/Library/Preferences/ui.wifiman-desktop.plist" ]; then
    rm -rf "$HOME/Library/Preferences/ui.wifiman-desktop.plist" 2>/dev/null || true
elif [ -f "$HOME/Library/Preferences/ui.wifiman-desktop.plist" ]; then
    rm -f "$HOME/Library/Preferences/ui.wifiman-desktop.plist" 2>/dev/null || true
fi

# Remove $HOME/Library/Saved Application State/ui.wifiman-desktop.savedState
echo "Removing $HOME/Library/Saved Application State/ui.wifiman-desktop.savedState..."
if [ -d "$HOME/Library/Saved Application State/ui.wifiman-desktop.savedState" ]; then
    rm -rf "$HOME/Library/Saved Application State/ui.wifiman-desktop.savedState" 2>/dev/null || true
elif [ -f "$HOME/Library/Saved Application State/ui.wifiman-desktop.savedState" ]; then
    rm -f "$HOME/Library/Saved Application State/ui.wifiman-desktop.savedState" 2>/dev/null || true
fi

echo "Uninstallation complete!"
exit 0
